		}
		foundValue = b.Get(k)
		if foundValue == nil {
			return fmt.Errorf("no value for this key %s", key)
		}
		return nil
	})
	if err != nil {
		log.Printf(err.Error())
		return nil, false
	}
	res, err := m.decodeValue(foundValue)
