def op_as_byte(code: mos_code_t, mode: mos_mode_t, res: Int) -> Int:
  code_was_found := False
  i = 0
  while i < sizeof(defs) / sizeof(defs[0]):
    if defs[i].code == code:
      code_was_found = True
      if defs[i].mode == mode:
        *res = defs[i].byte
        return 0
    i += 1
  if code_was_found:
    return MOS_INVALID_MODE
  return MOS_INVALID_OP
