	b.lock.RLock()
	unlockFunc := b.lock.RUnlock
	defer func() { unlockFunc() }()

	if b.client != nil && b.client.Valid() {
		return b.client, nil
	}

	b.lock.RUnlock()
	b.lock.Lock()
	unlockFunc = b.lock.Unlock

	if b.client != nil && b.client.Valid() {
		return b.client, nil
	}

	config, err := b.getConfig(ctx, s)
	if err != nil {
		return nil, err
	}

	c, err := NewClient(config)
	if err != nil {
		return nil, err
	}
	b.client = c

	return c, nil
}

func (b *ArtifactoryBackend) reset() {
	b.lock.Lock()
	defer b.lock.Unlock()

	b.client = nil
}

