function SbcHLi(cpu: Z80Cpu) {
    const src = cpu.readMemory(cpu.hl);
    cpu.tacts += 3;
    const carry = (cpu.f & FlagsSetMask.C) === 0 ? 0 : 1;
    cpu.f = sbcFlags[carry * 0x10000 + cpu.a * 0x100 + src];
    cpu.a -= src + carry;
}
```

